{"command": "create", "path": "/app/workspace/extract.py", "file_text": "import os
import re
import sys
from pathlib import Path
from datetime import date as _date

import pytesseract
from PIL import Image, ImageOps, ImageFilter
import openpyxl


IMG_DIR = Path("/app/workspace/dataset/img")
OUT_XLSX = Path("/app/workspace/stat_ocr.xlsx")

TIER_KEYWORDS = [
    ("GRAND TOTAL",),
    ("TOTAL RM", "TOTAL: RM"),
    ("TOTAL AMOUNT",),
    ("TOTAL", "AMOUNT", "TOTAL DUE", "AMOUNT DUE",
     "BALANCE DUE", "NETT TOTAL", "NET TOTAL"),
]

EXCLUSION_KEYWORDS = [
    "SUBTOTAL", "SUB TOTAL", "TAX", "GST", "SST",
    "DISCOUNT", "CHANGE", "CASH TENDERED",
]

PAYMENT_KEYWORDS = [
    "CASH", "CASH RECEIVED", "CASH TENDERED", "TENDERED",
    "PAYMENT", "PAID", "RECEIVED", "CHANGE", "VISA",
    "MASTERCARD", "MASTER", "CARD", "CREDIT", "DEBIT",
]

TABLE_HEADER_TOKENS = [
    "DESCRIPTION", "ITEM", "QTY", "U.PRICE", "UNIT PRICE", "PRICE",
]

CUTOFF_PATTERNS = [
    re.compile(r"GST\s*SUMMARY"),
    re.compile(r"TAX\s*SUMMARY"),
    re.compile(r"SST\s*SUMMARY"),
    re.compile(r"AMOUNT\s*\(RM\)\s*TAX\s*\(RM\)"),
    re.compile(r"TAX\s*CODE"),
]

MONEY_RE = re.compile(r"(?<![\w.])(\d{1,3}(?:,\d{3})+\.\d{2}|\d+\.\d{2})(?![\w.])")

CONFUSABLES = str.maketrans({
    "O": "0", "o": "0", "Q": "0", "u": "0",
    "l": "1", "I": "1", "|": "1",
    "S": "5", "B": "8", "Z": "2", "G": "6",
})


def canon(line: str) -> str:
    s = re.sub(r"\s+", " ", line.strip().upper())
    s = s.rstrip(".,:;-")
    return s


def is_excluded(canon_line: str) -> bool:
    return any(k in canon_line for k in EXCLUSION_KEYWORDS)


def is_payment_line(canon_line: str) -> bool:
    return any(re.search(r"\b" + re.escape(k) + r"\b", canon_line)
               for k in PAYMENT_KEYWORDS)


def is_table_header(canon_line: str, tier_tokens) -> bool:
    if not any(tok in canon_line for tok in tier_tokens):
        return False
    others = sum(1 for tok in TABLE_HEADER_TOKENS if tok in canon_line)
    return others >= 1


def find_cutoff(canon_lines):
    for i, cl in enumerate(canon_lines):
        for pat in CUTOFF_PATTERNS:
            if pat.search(cl):
                return i
    return len(canon_lines)


def parse_money_tokens(text: str):
    return MONEY_RE.findall(text)


def normalize_amount_token(tok: str) -> str:
    return tok.replace(",", "")


def try_fix_amount_in_line(line: str) -> list:
    """Try confusable substitution on dominated-numeric spans in a line."""
    # Find spans that look mostly numeric (allowing confusables and separators)
    results = []
    for m in re.finditer(r"[\dOoQulI|SBZGu.,]{3,}", line):
        span = m.group(0)
        if sum(c.isdigit() for c in span) < max(1, len(span) // 2):
            continue
        fixed = span.translate(CONFUSABLES)
        for mm in MONEY_RE.finditer(fixed):
            results.append(mm.group(1))
    return results


def extract_total(text: str):
    raw_lines = [l for l in text.splitlines() if l.strip()]
    canon_lines = [canon(l) for l in raw_lines]
    cutoff = find_cutoff(canon_lines)

    for tier in TIER_KEYWORDS:
        candidates = []
        for i, cl in enumerate(canon_lines):
            if i >= cutoff:
                break
            if not any(k in cl for k in tier):
                continue
            if is_excluded(cl):
                continue
            if is_table_header(cl, tier):
                continue
            candidates.append(i)

        for i in reversed(candidates):
            raw = raw_lines[i]
            toks = parse_money_tokens(raw)
            if toks:
                return normalize_amount_token(toks[-1])
            # try confusable fix on the keyword line itself
            fixed_toks = try_fix_amount_in_line(raw)
            if fixed_toks:
                return normalize_amount_token(fixed_toks[-1])
            # split-line fallback only if keyword line has NO digits at all
            if not any(c.isdigit() for c in raw):
                # look at next non-empty eligible line
                for j in range(i + 1, min(len(raw_lines), cutoff)):
                    nl_canon = canon_lines[j]
                    if is_excluded(nl_canon) or is_payment_line(nl_canon):
                        continue
                    ntoks = parse_money_tokens(raw_lines[j])
                    if ntoks:
                        return normalize_amount_token(ntoks[-1])
                    break
    return None


DATE_LABEL_RE = re.compile(r"\b(DATE|DATA|DAIE|INVOICE DATE)\b")
DATE_NEG_RE = re.compile(r"\b(PRINT|CLOSED|CLOSING|FRN|LOYALTY|PROMO)\b")

DATE_PATTERNS = [
    # DD/MM/YYYY  DD-MM-YYYY  DD.MM.YYYY
    re.compile(r"(\d{1,2})[\-/.](\d{1,2})[\-/.](\d{2,4})"),
]


def parse_date_candidates(text: str):
    """Return list of (day, month, year, line_index, has_label, has_neg)."""
    lines = text.splitlines()
    cands = []
    for i, line in enumerate(lines):
        cl = canon(line)
        has_label = bool(DATE_LABEL_RE.search(cl))
        has_neg = bool(DATE_NEG_RE.search(cl))
        for pat in DATE_PATTERNS:
            for m in pat.finditer(line):
                a, b, c = m.group(1), m.group(2), m.group(3)
                cands.append((a, b, c, i, has_label, has_neg))
    return cands


def validate_dmy(d, m, y):
    try:
        d, m, y = int(d), int(m), int(y)
        if y < 100:
            y += 2000
        if y < 2000 or y > 2099:
            return None
        _date(y, m, d)
        return (y, m, d)
    except Exception:
        return None


def extract_date(text: str):
    cands = parse_date_candidates(text)
    if not cands:
        # try confusable salvage on date-like text near label
        return None

    # Prefer label-bound non-negated
    scored = []
    for a, b, c, i, has_label, has_neg in cands:
        if has_neg:
            continue
        score = 2 if has_label else 0
        v = validate_dmy(a, b, c)
        if v:
            scored.append((score, i, v))
    if not scored:
        # fallback: non-negated anywhere
        for a, b, c, i, has_label, has_neg in cands:
            if has_neg:
                continue
            v = validate_dmy(a, b, c)
            if v:
                scored.append((0, i, v))
    if not scored:
        return None
    # highest score, then earliest line
    scored.sort(key=lambda x: (-x[0], x[1]))
    y, m, d = scored[0][2]
    return f"{y:04d}-{m:02d}-{d:02d}"


def ocr_variants(img_path: Path):
    """Yield OCR text for several preprocessing variants / PSM modes."""
    img = Image.open(img_path)
    gray = ImageOps.grayscale(img)

    variants = []
    variants.append(("auto1x", ImageOps.autocontrast(gray)))
    # 2x upscale with autocontrast
    w, h = gray.size
    up2 = gray.resize((w * 2, h * 2), Image.LANCZOS)
    variants.append(("auto2x", ImageOps.autocontrast(up2)))
    variants.append(("sharp1x", ImageOps.autocontrast(gray).filter(ImageFilter.SHARPEN)))

    psms = ["--psm 6", "--psm 4", "--psm 11"]
    for name, v in variants:
        for psm in psms:
            try:
                text = pytesseract.image_to_string(v, config=psm)
            except Exception:
                text = ""
            yield (f"{name}:{psm}", text)


def extract_one(img_path: Path, debug=False):
    best_total = None
    best_date = None
    totals_votes = {}
    dates_votes = {}
    for tag, text in ocr_variants(img_path):
        t = extract_total(text)
        d = extract_date(text)
        if t:
            try:
                tval = f"{float(t):.2f}"
            except ValueError:
                tval = None
            if tval:
                totals_votes[tval] = totals_votes.get(tval, 0) + 1
        if d:
            dates_votes[d] = dates_votes.get(d, 0) + 1
        if debug:
            print(f"--- {img_path.name} [{tag}] total={t} date={d}")

    if totals_votes:
        best_total = max(totals_votes.items(), key=lambda x: (x[1], x[0]))[0]
    if dates_votes:
        best_date = max(dates_votes.items(), key=lambda x: (x[1], x[0]))[0]
    return best_date, best_total


def main():
    debug = "--debug" in sys.argv
    files = sorted(p for p in IMG_DIR.iterdir()
                   if p.suffix.lower() in (".jpg", ".jpeg", ".png", ".webp"))

    rows = []
    for p in files:
        d, t = extract_one(p, debug=debug)
        print(f"{p.name}\tdate={d}\ttotal={t}")
        rows.append((p.name, d, t))

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])
    for name, d, t in rows:
        ws.append([name, d if d else None, t if t else None])
    wb.save(OUT_XLSX)
    print(f"Wrote {OUT_XLSX}")


if __name__ == "__main__":
    main()
"}

